<?php
declare(strict_types=1);

final class TaskReplanRepository
{
    private const ACTIVE = ['checkpointed','processing','proposed','pending_approval','approved'];
    private const REPLACEABLE = ['pending','ready'];

    public function __construct(private mysqli $db) {}

    public function claim(string $worker, int $leaseSeconds, int $maxAttempts): ?array
    {
        $this->db->begin_transaction();
        try {
            $s=$this->p("SELECT r.*,t.public_id task_public_id,t.title task_title,t.objective,t.status task_status,t.mode task_mode,t.lock_version task_lock,c.public_id cycle_public_id,c.status cycle_status,a.mode autonomy_mode,a.status policy_status FROM TaskReplanRequests r JOIN Tasks t ON t.id_=r.task_id_ AND t.user_id_=r.user_id_ AND t.project_id_=r.project_id_ JOIN ProjectAutonomyCycles c ON c.id_=r.autonomy_cycle_id_ AND c.user_id_=r.user_id_ AND c.project_id_=r.project_id_ JOIN ProjectAutonomyPolicies a ON a.id_=c.policy_id_ WHERE a.status='active' AND a.mode<>'disabled' AND ((r.status IN ('checkpointed','approved') AND (r.lease_expires_at IS NULL OR r.lease_expires_at<NOW(6))) OR (r.status='processing' AND r.lease_expires_at<NOW(6))) AND r.attempt_count<? ORDER BY r.created_at,r.id_ LIMIT 1 FOR UPDATE SKIP LOCKED");
            $s->bind_param('i',$maxAttempts);$this->x($s);$row=$s->get_result()->fetch_assoc();$s->close();
            if(!$row){$this->db->commit();return null;}
            $token=TaskWorkerConfig::leaseToken();$id=(int)$row['id_'];$original=(string)$row['status'];
            $s=$this->p("UPDATE TaskReplanRequests SET status=IF(status='approved','approved','processing'),worker_id=?,lease_token=?,lease_expires_at=DATE_ADD(NOW(6),INTERVAL ? SECOND),attempt_count=attempt_count+1,lock_version=lock_version+1 WHERE id_=? AND status IN ('checkpointed','processing','approved')");
            $s->bind_param('ssii',$worker,$token,$leaseSeconds,$id);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('replan_claim_lost');$s->close();
            $this->event((int)$row['task_id_'],$original==='approved'?'replan_retried':'replan_started',$original==='approved'?'Apply de revisión recuperado.':'Replanning iniciado.',(string)$row['public_id']);$this->db->commit();$row['worker_id']=$worker;$row['lease_token']=$token;$row['attempt_count']=(int)$row['attempt_count']+1;$row['status']=$original==='approved'?'approved':'processing';return$row;
        } catch(Throwable $e){$this->db->rollback();throw $e;}
    }

    public function snapshot(array $claim): TaskReplanSnapshot
    {
        $s=$this->p("SELECT s.id_,s.step_key,s.title,s.description,s.step_type,s.status,s.agent_key,LEFT(COALESCE(s.output_summary,''),1200) output_summary,LEFT(COALESCE(s.error_message,''),800) error_summary FROM TaskSteps s WHERE s.task_id_=? ORDER BY s.position,s.id_ LIMIT 100");$s->bind_param('i',$claim['task_id_']);$this->x($s);$steps=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
        if(count($steps)>64)throw new TaskValidationException('replan_history_limit');
        $source=null;foreach($steps as$row)if((int)$row['id_']===(int)$claim['source_step_id_']){$source=$row;break;}if(!$source)throw new TaskValidationException('replan_source_missing');
        return new TaskReplanSnapshot(['task'=>['public_id'=>(string)$claim['task_public_id'],'title'=>mb_substr((string)$claim['task_title'],0,255),'objective'=>mb_substr((string)$claim['objective'],0,8000),'mode'=>(string)$claim['task_mode'],'status'=>(string)$claim['task_status']],'source_failure'=>['step_key'=>(string)$source['step_key'],'title'=>(string)$source['title'],'step_type'=>(string)$source['step_type'],'trigger_code'=>(string)$claim['trigger_code'],'public_reason'=>mb_substr((string)$claim['public_reason'],0,500),'error_summary'=>(string)$source['error_summary']],'steps'=>array_map(fn($r)=>['step_key'=>(string)$r['step_key'],'title'=>mb_substr((string)$r['title'],0,255),'step_type'=>(string)$r['step_type'],'status'=>(string)$r['status'],'agent_key'=>mb_substr((string)$r['agent_key'],0,80),'output_summary'=>mb_substr((string)$r['output_summary'],0,1200)],$steps)]);
    }

    public function propose(array $claim, TaskPlanningResult $result): array
    {
        $payload=['steps'=>array_map(fn(TaskPlanStep $s)=>['step_key'=>$s->stepKey,'title'=>$s->title,'description'=>$s->description,'step_type'=>$s->stepType,'agent_key'=>$s->agentKey],$result->plan->steps())];$json=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);if(strlen($json)>20000)throw new TaskValidationException('replan_plan_too_large');
        $this->db->begin_transaction();try{$request=$this->lockClaim($claim);$existing=$this->revisionByRequest((int)$request['id_'],true);if($existing){$this->db->commit();return$existing;}$task=$this->lockTask((int)$request['task_id_']);$this->assertSafe($request,$task);$s=$this->p('SELECT COALESCE(MAX(revision_number),0) n FROM TaskPlanRevisions WHERE task_id_=? FOR UPDATE');$s->bind_param('i',$request['task_id_']);$this->x($s);$source=(int)$s->get_result()->fetch_assoc()['n'];$s->close();if($source===0)$this->createBaseRevision($request,$task,$source=1);$number=$source+1;$public=TaskPublicId::generate();$model=$result->model;$usage=json_encode($result->usage,JSON_THROW_ON_ERROR);$s=$this->p("INSERT INTO TaskPlanRevisions(public_id,user_id_,project_id_,task_id_,replan_request_id_,revision_number,source_revision,status,proposed_plan_json,planner_model,usage_json,public_reason) VALUES(?,?,?,?,?,?,?,'proposed',?,?,?,?)");$reason=mb_substr((string)$request['public_reason'],0,500);$s->bind_param('siiiiiissss',$public,$request['user_id_'],$request['project_id_'],$request['task_id_'],$request['id_'],$number,$source,$json,$model,$usage,$reason);$this->x($s);$revisionId=(int)$this->db->insert_id;$s->close();$next=((string)$request['autonomy_mode']==='automatic'&&(string)$task['mode']==='automatic')?'approved':'pending_approval';$s=$this->p("UPDATE TaskReplanRequests SET status=?,revision_id_=?,reservation_id_=?,lease_expires_at=NULL,worker_id=NULL,lease_token=NULL,lock_version=lock_version+1 WHERE id_=? AND status='processing'");$reservation=$request['reservation_id_'];$s->bind_param('siii',$next,$revisionId,$reservation,$request['id_']);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('replan_propose_conflict');$s->close();$s=$this->p("UPDATE TaskPlanRevisions SET status=? WHERE id_=?");$revisionStatus=$next==='approved'?'approved':'pending_approval';$s->bind_param('si',$revisionStatus,$revisionId);$this->x($s);$s->close();$this->event((int)$request['task_id_'],'replan_proposed','Revisión de plan propuesta.',(string)$request['public_id']);$this->event((int)$request['task_id_'],$next==='approved'?'replan_approved':'replan_waiting_approval',$next==='approved'?'Revisión autorizada automáticamente.':'Revisión esperando aprobación.',(string)$request['public_id']);$row=$this->revisionByRequest((int)$request['id_'],true);$this->db->commit();return$row??throw new RuntimeException('replan_revision_missing');}catch(Throwable$e){$this->db->rollback();throw$e;}
    }

    public function apply(int $userId,string $requestPublicId,?int $expectedLock=null):array
    {
        $this->db->begin_transaction();try{$s=$this->p("SELECT r.*,a.mode autonomy_mode,a.status policy_status,c.status cycle_status FROM TaskReplanRequests r JOIN ProjectAutonomyCycles c ON c.id_=r.autonomy_cycle_id_ JOIN ProjectAutonomyPolicies a ON a.id_=c.policy_id_ WHERE r.user_id_=? AND r.public_id=? FOR UPDATE");$s->bind_param('is',$userId,$requestPublicId);$this->x($s);$request=$s->get_result()->fetch_assoc();$s->close();if(!$request)throw new TaskNotFoundException('replan_not_found');if($request['status']==='applied'){$row=$this->revisionByRequest((int)$request['id_'],true);$this->db->commit();return$row??throw new RuntimeException('replan_revision_missing');}if($expectedLock!==null&&(int)$request['lock_version']!==$expectedLock)throw new TaskConcurrencyException('replan_lock_conflict');if(!in_array($request['status'],['approved','pending_approval'],true))throw new TaskTransitionException('replan_not_approved');if($request['status']==='pending_approval')throw new TaskTransitionException('replan_approval_required');if($request['policy_status']!=='active'||$request['cycle_status']!=='active'||$request['autonomy_mode']==='disabled')throw new TaskTransitionException('autonomy_not_active');$task=$this->lockTask((int)$request['task_id_']);$this->assertSafe($request,$task);$revision=$this->revisionByRequest((int)$request['id_'],true)??throw new RuntimeException('replan_revision_missing');if((int)$revision['source_revision']!==$this->currentRevision((int)$request['task_id_']))throw new TaskConcurrencyException('replan_stale');$plan=json_decode((string)$revision['proposed_plan_json'],true,32,JSON_THROW_ON_ERROR);$steps=$plan['steps']??[];if(!is_array($steps)||$steps===[])throw new TaskValidationException('replan_plan_invalid');$s=$this->p("SELECT COUNT(*) n,MAX(position) max_position FROM TaskSteps WHERE task_id_=?");$s->bind_param('i',$request['task_id_']);$this->x($s);$counts=$s->get_result()->fetch_assoc();$s->close();if((int)$counts['n']+count($steps)>100)throw new TaskValidationException('replan_historical_steps_limit');$s=$this->p("UPDATE TaskSteps SET status='cancelled',completed_at=NOW(6),lock_version=lock_version+1 WHERE task_id_=? AND status IN ('pending','ready')");$s->bind_param('i',$request['task_id_']);$this->x($s);$s->close();$position=(int)$counts['max_position'];$firstId=null;foreach($steps as$i=>$raw){$position++;$logical=(string)$raw['step_key'];$key='r'.(int)$revision['revision_number'].'_'.$logical;if(strlen($key)>80)$key='r'.(int)$revision['revision_number'].'_'.substr(hash('sha256',$logical),0,20);$status=$i===0?'ready':'pending';$input=json_encode(['execution_mode'=>'async'],JSON_THROW_ON_ERROR);$s=$this->p('INSERT INTO TaskSteps(task_id_,position,step_key,title,description,step_type,status,agent_key,max_attempts,input_json) VALUES(?,?,?,?,?,?,?,?,1,?)');$s->bind_param('iisssssss',$request['task_id_'],$position,$key,$raw['title'],$raw['description'],$raw['step_type'],$status,$raw['agent_key'],$input);$this->x($s);$stepId=(int)$this->db->insert_id;$s->close();$firstId??=$stepId;$s=$this->p('INSERT INTO TaskPlanRevisionSteps(revision_id_,step_id_,logical_key,position_in_revision) VALUES(?,?,?,?)');$pos=$i+1;$s->bind_param('iisi',$revision['id_'],$stepId,$logical,$pos);$this->x($s);$s->close();}$s=$this->p("UPDATE Tasks SET status='ready',current_step_id_=?,error_code=NULL,error_message=NULL,completed_at=NULL,lock_version=lock_version+1 WHERE id_=? AND status='failed' AND lock_version=?");$s->bind_param('iii',$firstId,$request['task_id_'],$request['source_task_lock_version']);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('replan_task_stale');$s->close();$s=$this->p("UPDATE TaskPlanRevisions SET status='applied',applied_at=NOW(6),lock_version=lock_version+1 WHERE id_=? AND status='approved'");$s->bind_param('i',$revision['id_']);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('replan_revision_conflict');$s->close();$s=$this->p("UPDATE TaskReplanRequests SET status='applied',applied_at=NOW(6),lock_version=lock_version+1 WHERE id_=? AND status='approved'");$s->bind_param('i',$request['id_']);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('replan_apply_conflict');$s->close();$this->event((int)$request['task_id_'],'replan_applied','Revisión aplicada; la Task vuelve a ready.',(string)$request['public_id']);$row=$this->revisionByRequest((int)$request['id_'],true);$this->db->commit();return$row??throw new RuntimeException('replan_revision_missing');}catch(Throwable$e){$this->db->rollback();throw$e;}
    }

    public function approve(int$u,string$public,int$lock):array{$this->db->begin_transaction();try{$s=$this->p("UPDATE TaskReplanRequests r JOIN Tasks t ON t.id_=r.task_id_ JOIN ProjectAutonomyCycles c ON c.id_=r.autonomy_cycle_id_ JOIN ProjectAutonomyPolicies a ON a.id_=c.policy_id_ SET r.status='approved',r.approved_at=NOW(6),r.lock_version=r.lock_version+1 WHERE r.user_id_=? AND r.public_id=? AND r.lock_version=? AND r.status='pending_approval' AND t.status='failed' AND c.status='active' AND a.status='active' AND a.mode<>'disabled'");$s->bind_param('isi',$u,$public,$lock);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('replan_approval_conflict');$s->close();$s=$this->p("UPDATE TaskPlanRevisions v JOIN TaskReplanRequests r ON r.revision_id_=v.id_ SET v.status='approved',v.approved_at=NOW(6),v.lock_version=v.lock_version+1 WHERE r.user_id_=? AND r.public_id=? AND v.status='pending_approval'");$s->bind_param('is',$u,$public);$this->x($s);$s->close();$this->eventForOwned($u,$public,'replan_approved','Revisión aprobada por el usuario.');$this->db->commit();return$this->apply($u,$public);}catch(Throwable$e){$this->db->rollback();throw$e;}}
    public function reject(int$u,string$public,int$lock):array{$s=$this->p("UPDATE TaskReplanRequests r LEFT JOIN TaskPlanRevisions v ON v.id_=r.revision_id_ SET r.status='rejected',r.rejected_at=NOW(6),r.lock_version=r.lock_version+1,v.status=IF(v.status='pending_approval','rejected',v.status),v.rejected_at=IF(v.status='pending_approval',NOW(6),v.rejected_at) WHERE r.user_id_=? AND r.public_id=? AND r.lock_version=? AND r.status IN ('checkpointed','pending_approval')");$s->bind_param('isi',$u,$public,$lock);$this->x($s);if($s->affected_rows<1)throw new TaskConcurrencyException('replan_reject_conflict');$s->close();$this->eventForOwned($u,$public,'replan_rejected','Revisión rechazada por el usuario.');return['status'=>'rejected'];}
    public function attachReservation(array$claim,int$reservationId):void{$s=$this->p("UPDATE TaskReplanRequests SET reservation_id_=? WHERE id_=? AND worker_id=? AND lease_token=? AND status='processing'");$s->bind_param('iiss',$reservationId,$claim['id_'],$claim['worker_id'],$claim['lease_token']);$this->x($s);$s->close();}
    public function reservationId(int$u,int$p,string$public):int{$s=$this->p('SELECT id_ FROM ProjectAutonomyReservations WHERE user_id_=? AND project_id_=? AND public_id=?');$s->bind_param('iis',$u,$p,$public);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return(int)($r['id_']??throw new TaskValidationException('replan_reservation_scope'));}
    public function failClaim(array$claim,string$reason,bool$retry,int$max):void{$terminal=!$retry||(int)$claim['attempt_count']>=$max;$status=$terminal?'failed':((string)$claim['status']==='approved'?'approved':'checkpointed');$delay=min(300,5*(2**max(0,(int)$claim['attempt_count']-1)));$s=$this->p("UPDATE TaskReplanRequests SET status=?,failure_reason=?,next_attempt_at=DATE_ADD(NOW(6),INTERVAL ? SECOND),failed_at=IF(?='failed',NOW(6),failed_at),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,lock_version=lock_version+1 WHERE id_=? AND worker_id=? AND lease_token=? AND status IN ('processing','approved')");$s->bind_param('ssisiss',$status,$reason,$delay,$status,$claim['id_'],$claim['worker_id'],$claim['lease_token']);$this->x($s);$s->close();$this->event((int)$claim['task_id_'],$terminal?'replan_failed':'replan_retried',$terminal?'Replanning detenido.':'Replanning reintentable.',(string)$claim['public_id']);}

    private function lockClaim(array$claim):array{$s=$this->p("SELECT r.*,a.mode autonomy_mode,a.status policy_status,c.status cycle_status FROM TaskReplanRequests r JOIN ProjectAutonomyCycles c ON c.id_=r.autonomy_cycle_id_ JOIN ProjectAutonomyPolicies a ON a.id_=c.policy_id_ WHERE r.id_=? AND r.worker_id=? AND r.lease_token=? AND r.status='processing' FOR UPDATE");$s->bind_param('iss',$claim['id_'],$claim['worker_id'],$claim['lease_token']);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:throw new TaskConcurrencyException('replan_claim_lost');}
    private function lockTask(int$id):array{$s=$this->p('SELECT * FROM Tasks WHERE id_=? FOR UPDATE');$s->bind_param('i',$id);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:throw new TaskNotFoundException('replan_task_missing');}
    private function assertSafe(array$r,array$t):void{if($t['status']!=='failed'||(int)$t['lock_version']!==(int)$r['source_task_lock_version']||$r['cycle_status']!=='active'||$r['policy_status']!=='active'||$r['autonomy_mode']==='disabled')throw new TaskTransitionException('unsafe_replan_checkpoint');$s=$this->p("SELECT EXISTS(SELECT 1 FROM TaskExecutions WHERE task_id_=? AND status IN ('queued','running','waiting')) active_execution,EXISTS(SELECT 1 FROM TaskSteps WHERE task_id_=? AND status IN ('running','waiting_user','waiting_dependency')) incompatible_step");$s->bind_param('ii',$r['task_id_'],$r['task_id_']);$this->x($s);$x=$s->get_result()->fetch_assoc();$s->close();if((int)$x['active_execution']!==0||(int)$x['incompatible_step']!==0)throw new TaskTransitionException('unsafe_replan_checkpoint');}
    private function createBaseRevision(array$r,array$t,int$n):void{$public=TaskPublicId::generate();$s=$this->p("INSERT INTO TaskPlanRevisions(public_id,user_id_,project_id_,task_id_,revision_number,source_revision,status,proposed_plan_json,public_reason,applied_at) VALUES(?,?,?,?,?,0,'historical',JSON_OBJECT('steps',JSON_ARRAY()),'Initial plan history',NOW(6))");$s->bind_param('siiii',$public,$r['user_id_'],$r['project_id_'],$r['task_id_'],$n);$this->x($s);$revision=(int)$this->db->insert_id;$s->close();$s=$this->p('INSERT INTO TaskPlanRevisionSteps(revision_id_,step_id_,logical_key,position_in_revision) SELECT ?,id_,step_key,position FROM TaskSteps WHERE task_id_=?');$s->bind_param('ii',$revision,$r['task_id_']);$this->x($s);$s->close();}
    private function currentRevision(int$task):int{$s=$this->p("SELECT COALESCE(MAX(revision_number),0) n FROM TaskPlanRevisions WHERE task_id_=? AND status IN ('historical','applied')");$s->bind_param('i',$task);$this->x($s);$n=(int)$s->get_result()->fetch_assoc()['n'];$s->close();return$n;}
    private function revisionByRequest(int$id,bool$lock):?array{$sql='SELECT v.*,r.public_id request_public_id FROM TaskPlanRevisions v JOIN TaskReplanRequests r ON r.id_=v.replan_request_id_ WHERE v.replan_request_id_=?'.($lock?' FOR UPDATE':'');$s=$this->p($sql);$s->bind_param('i',$id);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:null;}
    private function eventForOwned(int$u,string$public,string$key,string$summary):void{$s=$this->p('SELECT task_id_ FROM TaskReplanRequests WHERE user_id_=? AND public_id=?');$s->bind_param('is',$u,$public);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();if($r)$this->event((int)$r['task_id_'],$key,$summary,$public);}
    private function event(int$task,string$key,string$summary,string$public):void{$s=$this->p("INSERT INTO TaskEvents(task_id_,actor_type,event_key,summary,details_json) VALUES(?,'system',?,?,JSON_OBJECT('replan_public_id',?))");$s->bind_param('isss',$task,$key,$summary,$public);$this->x($s);$s->close();}
    private function p(string$q):mysqli_stmt{$s=$this->db->prepare($q);if(!$s)throw new RuntimeException('replan_prepare_failed');return$s;}private function x(mysqli_stmt$s):void{if(!$s->execute())throw new RuntimeException('replan_query_failed');}
